void reviewSource(String source){if(reviewing)return;reviewing=true;try{context.removeAllViews();context.addView(description);description.setText("Source Problem

"+source+"

Reconnect storage or check access to this location. Library records and viewing progress are kept. Partial directory failures do not mark the whole source offline.");context.addView(SharedThreePanel.accentAction(getContext(),"Scan Library",()->PreviewLibraryScan.request(getContext())));}finally{reviewing=false;}}

private void info(LinearLayout row,String name,String value){TextView t=text(value.replace("

","    ·    ").replace("
",": "),13);t.setMaxLines(3);t.setEllipsize(android.text.TextUtils.TruncateAt.END);t.setTextColor(0xffa8becf);t.setPadding(0,dp(3),0,dp(3));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(7);row.addView(t,lp);}
